def validate_step(step: int, data: dict) -> dict:
    errors = {}
    if step == 1:
        email = data.get("email", "")
        if not isinstance(email, str):
            email = ""
        email_stripped = email.strip()
        if not email_stripped:
            errors["email"] = "Email is required"
        else:
            if email_stripped.count("@") != 1:
                errors["email"] = "Invalid email address"
            else:
                local, domain = email_stripped.split("@")
                if not local or "." not in domain:
                    errors["email"] = "Invalid email address"

    elif step == 2:
        password = data.get("password", "")
        if not isinstance(password, str):
            password = ""
        confirm_password = data.get("confirm_password", "")
        if not isinstance(confirm_password, str):
            confirm_password = ""

        # Validate password
        if len(password) < 8:
            errors["password"] = "Password must be at least 8 characters"
        elif not any(c.isupper() for c in password):
            errors["password"] = "Password must contain an uppercase letter"
        elif not any(c.islower() for c in password):
            errors["password"] = "Password must contain a lowercase letter"
        elif not any(c.isdigit() for c in password):
            errors["password"] = "Password must contain a digit"

        # Validate confirm_password
        if confirm_password != password:
            errors["confirm_password"] = "Passwords do not match"

    elif step == 3:
        full_name = data.get("full_name", "")
        if not isinstance(full_name, str):
            full_name = ""
        if not full_name.strip():
            errors["full_name"] = "Full name is required"

        accept_terms = data.get("accept_terms", False)
        if not accept_terms:
            errors["accept_terms"] = "You must accept the terms"

    return errors

import os
from validators import validate_step
from db import init_db, insert_registration, DB_PATH

def test_validators():
    print("Testing Step 1...")
    # Blank email
    assert validate_step(1, {"email": ""}) == {"email": "Email is required"}
    assert validate_step(1, {"email": "   "}) == {"email": "Email is required"}

    # Invalid email
    assert validate_step(1, {"email": "test"}) == {"email": "Invalid email address"}
    assert validate_step(1, {"email": "test@"}) == {"email": "Invalid email address"}
    assert validate_step(1, {"email": "test@com"}) == {"email": "Invalid email address"}
    assert validate_step(1, {"email": "@com.cn"}) == {"email": "Invalid email address"}
    assert validate_step(1, {"email": "test@abc@com.cn"}) == {"email": "Invalid email address"}

    # Valid email
    assert validate_step(1, {"email": "test@example.com"}) == {}
    assert validate_step(1, {"email": "  test@example.com  "}) == {}

    print("Testing Step 2...")
    # Password too short
    assert validate_step(2, {"password": "Short1", "confirm_password": "Short1"}) == {"password": "Password must be at least 8 characters"}

    # Password no uppercase
    assert validate_step(2, {"password": "password1", "confirm_password": "password1"}) == {"password": "Password must contain an uppercase letter"}

    # Password no lowercase
    assert validate_step(2, {"password": "PASSWORD1", "confirm_password": "PASSWORD1"}) == {"password": "Password must contain a lowercase letter"}

    # Password no digit
    assert validate_step(2, {"password": "Password", "confirm_password": "Password"}) == {"password": "Password must contain a digit"}

    # Password mismatch
    assert validate_step(2, {"password": "Password1", "confirm_password": "Password2"}) == {"confirm_password": "Passwords do not match"}

    # Valid password
    assert validate_step(2, {"password": "Password1", "confirm_password": "Password1"}) == {}

    print("Testing Step 3...")
    # Full name blank
    assert validate_step(3, {"full_name": "", "accept_terms": True}) == {"full_name": "Full name is required"}
    assert validate_step(3, {"full_name": "   ", "accept_terms": True}) == {"full_name": "Full name is required"}

    # Accept terms falsy
    assert validate_step(3, {"full_name": "John Doe", "accept_terms": False}) == {"accept_terms": "You must accept the terms"}

    # Both invalid
    assert validate_step(3, {"full_name": "", "accept_terms": False}) == {"full_name": "Full name is required", "accept_terms": "You must accept the terms"}

    # Valid Step 3
    assert validate_step(3, {"full_name": "John Doe", "accept_terms": True}) == {}

    print("All validators tests passed!")

def test_db():
    print("Testing DB...")
    if os.path.exists(DB_PATH):
        os.remove(DB_PATH)

    init_db()
    assert os.path.exists(DB_PATH)

    reg_id = insert_registration("test@example.com", "John Doe", "Password123")
    assert isinstance(reg_id, int)
    assert reg_id > 0

    # Verify record in sqlite
    import sqlite3
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute("SELECT email, full_name, password_hash, created_at FROM registrations WHERE id = ?", (reg_id,))
    row = cursor.fetchone()
    conn.close()

    assert row is not None
    assert row[0] == "test@example.com"
    assert row[1] == "John Doe"

    # check hash
    import hashlib
    expected_hash = hashlib.sha256("Password123".encode("utf-8")).hexdigest()
    assert row[2] == expected_hash
    assert row[3] is not None # ISO timestamp
    print("All DB tests passed!")

if __name__ == "__main__":
    test_validators()
    test_db()
